@Override public void onUserNotice(final UserNotice msg) {
  final String user = msg.getSource().getNick();
  try {
    final Contact from = MessageManager.this.provider.getPersistentPresence().findOrCreateContactByID(user);
    final MessageIrcImpl message = MessageIrcImpl.newNoticeFromIRC(from, msg.getText());
    MessageManager.this.provider.getBasicInstantMessaging().fireMessageReceived(message, from);
  } catch (NoSuchElementException | UnsupportedOperationException | IllegalArgumentException | ClassCastException | IndexOutOfBoundsException | EmptyStackException e) {
    // Handle the exception, e.g., log the error or provide a fallback action
    e.printStackTrace();
  }
}
